entries.anchor:
{mode === "dm" ? (
        <Dm
          dms={mesh.signals.dms}
          dmVisible={mesh.status.dmVisible}
          width={size.cols}
          height={bodyH}
          narrow={narrow}
          blocked={blocked}
          onFocus={onFocus}
        />
      ) : mode === "topo" ? (
        <Topo
          feed={mesh.feed}
          agents={mesh.agents}
          variant={topoVariant}
          width={size.cols}
          height={bodyH}
          blocked={blocked}
          onFocus={onFocus}
          onOpenAgent={openAgent}
          onOpenMessage={openMessage}
        />
      ) : (
        <Box flexDirection={narrow ? "column" : "row"} height={bodyH}>
          <Box flexDirection={narrow ? "column" : "row"} width={bodyW} height={bodyH}>
            <Roster
              agents={mesh.agents}
              endpoints={mesh.endpoints}
              query={search.query}
              boxWidth={roster.w}
              boxHeight={roster.h}
              wide={!narrow}
              blocked={blocked}
              onFocus={onFocus}
              onOpenDetail={openAgent}
              onKill={canWrite ? handleKill : undefined}
              onCompose={canWrite ? rosterCompose : undefined}
            />
            <Feed
              entries={mesh.feed}
              activeChannel={activeChannel}
              query={search.query}
              boxWidth={feed.w}
              boxHeight={feed.h}
              blocked={blocked}
              onFocus={onFocus}
              onOpenDetail={openMessage}
              onCompose={canWrite ? feedCompose : undefined}
              onReply={canWrite ? feedReply : undefined}
            />
          </Box>
          {railAsColumn ? (
            <NeedsYou
              waiting={mesh.signals.waiting}
              boxWidth={railW}
              boxHeight={bodyH}
              blocked={blocked}
              onFocus={onFocus}
              onOpenDetail={openAgent}
            />
          ) : null}
        </Box>
      )}

{railAsColumn ? (
            <NeedsYou
              waiting={mesh.signals.waiting}
              boxWidth={railW}
              boxHeight={bodyH}
              blocked={blocked}
              onFocus={onFocus}
              onOpenDetail={openAgent}
            />
          ) : null}

{compose ? (
        <Prompt
          label={composeLabel(compose)}
          value={compose.value}
          width={size.cols}
          onChange={(v) => setCompose((c) => (c ? { ...c, value: v } : c))}
          onSubmit={submitCompose}
          onCancel={() => setCompose(null)}
        />
      ) : palette.active ? (
        <CommandPalette
          active={palette.active}
          query={palette.query}
          snapshot={mesh}
          canWrite={!!canWrite}
          width={size.cols}
          onChange={(q) => setPalette((p) => ({ ...p, query: q }))}
          onRun={runPaletteLine}
          onCancel={() => setPalette({ active: false, query: "" })}
        />
      ) : searchRow ? (
        <Search
          query={search.query}
          active={search.active}
          width={size.cols}
          onChange={(q) => setSearch((s) => ({ ...s, query: q }))}
          onSubmit={() => setSearch((s) => ({ ...s, active: false }))}
          onCancel={() => setSearch({ active: false, query: "" })}
        />
      ) : null}

{wide ? (
        isAgent ? (
          <Text color={s.color}>{"  " + s.word}</Text>
        ) : (
          <Text dimColor>{"  endpoint"}</Text>
        )
      ) : null}

